package com.fitconnect.payment.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ProblemDetail> error(IllegalArgumentException e){return ResponseEntity.status(404).body(ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,e.getMessage()));}}
